/**
 * lite-sandbox for opencode v2.
 *
 * Generated by `lite-sandbox install opencode` (or `lite-sandbox launch
 * opencode`); a reinstall rewrites this file, so do not edit it. It forwards
 * each call of opencode's built-in shell, file, patch and media tools, and of
 * the sandbox's own bash tool, to `lite-sandbox hook`:
 *
 *  - a denial rejects the call, with the hook's reason as the tool's error.
 *    That confines the file tools to the sandbox's readable and writable
 *    paths and keeps the built-in shell blocked;
 *  - an "ask" (a `lite-sandbox config` request, or a command the sandbox's
 *    config asks about) is put to the user through opencode's own permission
 *    prompt, and the call runs only if they allow it once.
 *
 * Whenever the hook cannot give an answer (it is missing, fails, or times
 * out) the call is rejected. Code Mode programs' tool calls go through the
 * same hook, so they are checked one by one. What a program does other than
 * call a tool (with opencode's experimental full_codemode flag, its own file
 * access) never reaches this hook.
 */
import { spawn } from "node:child_process"

interface LiteSandboxConfig {
  /** Absolute path of the lite-sandbox binary. */
  bin: string
  /** Arguments for `lite-sandbox hook`. */
  hookArgs: string[]
  /** opencode's built-in tools whose calls are forwarded to the hook. */
  tools: string[]
  /** The sandbox's bash tool, as opencode names it in its tool hooks. */
  sandboxBash: string
  /** Other spellings of the sandbox's bash tool a call may use. */
  sandboxBashAliases: string[]
  /** Seconds to wait for the hook before rejecting the call. */
  hookTimeoutSec: number
}

const CONFIG: LiteSandboxConfig = __LITE_SANDBOX_CONFIG__

/**
 * The permission action of the plugin's approval prompts is this prefix and
 * the first line of the hook's reason: opencode's TUI shows a plugin's
 * request by its action alone.
 */
const ACTION_PREFIX = "lite-sandbox: "

type Decision = { decision: "allow" | "deny" | "ask" | ""; reason: string }

/** Runs `lite-sandbox hook` on one PreToolUse event and returns its decision. */
function runHook(event: Record<string, unknown>): Promise<Decision> {
  return new Promise((resolve, reject) => {
    const child = spawn(CONFIG.bin, CONFIG.hookArgs, { stdio: ["pipe", "pipe", "pipe"] })
    let stdout = ""
    let stderr = ""
    let settled = false
    const finish = (err: Error | undefined, value?: Decision) => {
      if (settled) return
      settled = true
      clearTimeout(timer)
      if (err) reject(err)
      else resolve(value as Decision)
    }
    const timer = setTimeout(() => {
      child.kill("SIGKILL")
      finish(new Error(`lite-sandbox hook did not answer within ${CONFIG.hookTimeoutSec}s`))
    }, CONFIG.hookTimeoutSec * 1000)

    child.stdout.setEncoding("utf8")
    child.stderr.setEncoding("utf8")
    child.stdout.on("data", (chunk: string) => (stdout += chunk))
    child.stderr.on("data", (chunk: string) => (stderr += chunk))
    child.on("error", (err) => finish(new Error(`could not run lite-sandbox hook (${CONFIG.bin}): ${err.message}`)))
    child.on("close", (code) => {
      if (code !== 0) {
        finish(new Error(`lite-sandbox hook exited with status ${code}: ${stderr.trim()}`))
        return
      }
      if (stdout.trim() === "") {
        // The hook defers: nothing for the sandbox to enforce.
        finish(undefined, { decision: "", reason: "" })
        return
      }
      try {
        const out = JSON.parse(stdout).hookSpecificOutput ?? {}
        finish(undefined, {
          decision: out.permissionDecision ?? "",
          reason: out.permissionDecisionReason ?? "",
        })
      } catch (err) {
        finish(new Error(`lite-sandbox hook printed an unreadable decision: ${String(err)}`))
      }
    })
    child.stdin.on("error", () => {
      // The hook exited before reading its input; "close" reports it.
    })
    child.stdin.end(JSON.stringify(event))
  })
}

/** The name the hook knows a call's tool by, or "" for a tool it does not govern. */
function governedName(tool: string): string {
  if (tool === CONFIG.sandboxBash || CONFIG.sandboxBashAliases.includes(tool)) return CONFIG.sandboxBash
  if (CONFIG.tools.includes(tool)) return tool
  return ""
}

export default {
  id: "lite-sandbox",
  setup: async (ctx: any) => {
    const cwd: string = ctx.location.directory

    // The plugin's own approval requests always ask: no configured or saved
    // rule may answer them in the user's place. A deny rule matching the
    // action is applied before this hook runs, and still rejects the call.
    await ctx.permission.hook("evaluate", (event: any) => {
      if (typeof event.action !== "string" || !event.action.startsWith(ACTION_PREFIX)) return
      event.effect = "ask"
      if (typeof event.metadata?.reason === "string") event.message = event.metadata.reason
    })

    await ctx.tool.hook("execute.before", async (event: any) => {
      const tool = governedName(event.tool)
      if (tool === "") return
      let result: Decision
      try {
        result = await runHook({
          hook_event_name: "PreToolUse",
          opencode_event: "tool.execute.before",
          cwd,
          session_id: event.sessionID,
          tool_name: tool,
          tool_input: event.input ?? {},
        })
      } catch (err) {
        throw new Error(`Blocked by lite-sandbox: ${err instanceof Error ? err.message : String(err)}`)
      }
      switch (result.decision) {
        case "deny":
          throw new Error(result.reason)
        case "ask": {
          const lines = result.reason.split("\n").filter((line) => line.trim() !== "")
          // Rejects (with the user's feedback, if any) unless the user allows
          // it once; omitting save leaves no "always allow" to choose.
          await ctx.permission.assert({
            sessionID: event.sessionID,
            agent: event.agent,
            action: ACTION_PREFIX + (lines[0] ?? tool),
            resources: lines.length > 0 ? lines : [tool],
            metadata: { reason: result.reason },
          })
          return
        }
        default:
          return
      }
    })
  },
}
